using Microsoft.EntityFrameworkCore; using pcms.Application.Inventory; using pcms.Domain.Entities; using pcms.Domain.Enums; using pcms.Infrastructure.Persistence;
namespace pcms.Infrastructure.Services;
public sealed class CremationInventoryService(AppDbContext db):ICremationInventoryService
{
 public async Task<CremationInventoryDto> GetAsync(Guid id){var c=await db.Cremations.AsNoTracking().Include(x=>x.Urn).FirstOrDefaultAsync(x=>x.Id==id)??throw new ArgumentException("La cremación no existe.");return await Map(c);}
 public async Task<CremationInventoryDto> ReserveAsync(Guid id,Guid? user){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var c=await db.Cremations.Include(x=>x.Urn).FirstOrDefaultAsync(x=>x.Id==id)??throw new ArgumentException("La cremación no existe.");if(!c.IncludesUrn||!c.UrnId.HasValue)return await Map(c);var m=await db.UrnSupplyItems.Include(x=>x.SupplyItem).FirstOrDefaultAsync(x=>x.UrnId==c.UrnId&&x.IsActive&&x.SupplyItem.IsActive&&x.SupplyItem.TrackInventory)??throw new InvalidOperationException("La urna no tiene un insumo terminado válido configurado.");if(await db.CremationUrnReservations.AnyAsync(x=>x.CremationId==id&&x.Status==UrnReservationStatus.Fulfilled))throw new InvalidOperationException("La urna ya fue entregada.");if(await db.CremationUrnReservations.AnyAsync(x=>x.CremationId==id&&x.Status==UrnReservationStatus.Active))return await Map(c);if(await Physical(m.SupplyItemId)-await db.CremationUrnReservations.CountAsync(x=>x.SupplyItemId==m.SupplyItemId&&x.Status==UrnReservationStatus.Active)<1)throw new InvalidOperationException("No hay urnas disponibles para reservar.");db.Add(new CremationUrnReservation{Id=Guid.NewGuid(),CremationId=id,UrnId=c.UrnId.Value,SupplyItemId=m.SupplyItemId,UrnNameSnapshot=c.Urn!.Name,SupplyItemNameSnapshot=m.SupplyItem.Name,SupplyItemScanCodeSnapshot=m.SupplyItem.ScanCode,Status=UrnReservationStatus.Active,ReservedAt=DateTime.UtcNow,ReservedByUserId=user});await db.SaveChangesAsync();await tx.CommitAsync();return await Map(c);}
 public async Task<CremationInventoryDto> CancelAsync(Guid id,Guid? user,string? reason){var r=await db.CremationUrnReservations.FirstOrDefaultAsync(x=>x.CremationId==id&&x.Status==UrnReservationStatus.Active)??throw new InvalidOperationException("No existe una reserva activa.");r.Status=UrnReservationStatus.Cancelled;r.CancelledAt=DateTime.UtcNow;r.CancelledByUserId=user;r.CancellationReason=reason;await db.SaveChangesAsync();return await GetAsync(id);}
 public async Task<CremationInventoryDto> FulfillAsync(Guid id,IReadOnlyCollection<FulfillmentMaterialInput> inputs,Guid? user){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var c=await db.Cremations.Include(x=>x.Urn).FirstOrDefaultAsync(x=>x.Id==id)??throw new ArgumentException("La cremación no existe.");if(await db.CremationInventoryFulfillments.AnyAsync(x=>x.CremationId==id))return await Map(c);var r=await db.CremationUrnReservations.FirstOrDefaultAsync(x=>x.CremationId==id&&x.Status==UrnReservationStatus.Active)??throw new InvalidOperationException("La cremación no tiene una reserva activa.");var ms=inputs.GroupBy(x=>x.SupplyItemId).Select(g=>new{Id=g.Key,Q=g.Sum(x=>x.Quantity),Lot=g.Select(x=>x.LotId).Distinct().SingleOrDefault()});foreach(var x in ms){if(x.Q<=0)throw new ArgumentException("Las cantidades deben ser mayores que cero.");if(!await db.SupplyItems.AnyAsync(i=>i.Id==x.Id&&i.IsActive&&i.TrackInventory))throw new ArgumentException("Material inválido.");await Check(x.Id,x.Q,x.Lot,x.Id==r.SupplyItemId);}if(await Physical(r.SupplyItemId)<1)throw new InvalidOperationException("No hay existencia física de la urna reservada.");var f=new CremationInventoryFulfillment{Id=Guid.NewGuid(),CremationId=id, CremationUrnReservationId=r.Id,FulfilledAt=DateTime.UtcNow,FulfilledByUserId=user};var um=Move(r.SupplyItemId,1,id,user,"Entrega de urna reservada");f.UrnMovementId=um.Id;db.Add(um);db.Add(f);foreach(var x in ms){var i=await db.SupplyItems.FirstAsync(i=>i.Id==x.Id);var m=Move(x.Id,x.Q,id,user,"Material adicional de entrega");m.SupplyInventoryLotId=x.Lot;db.Add(m);f.Materials.Add(new CremationInventoryMaterial{Id=Guid.NewGuid(),FulfillmentId=f.Id,SupplyItemId=x.Id,LotId=x.Lot,SupplyItemNameSnapshot=i.Name,UnitOfMeasureSnapshot=i.UnitOfMeasure,Quantity=decimal.Round(x.Q,3),InventoryMovementId=m.Id});}r.Status=UrnReservationStatus.Fulfilled;r.FulfilledAt=f.FulfilledAt;r.FulfilledByUserId=user;r.FulfillmentId=f.Id;await db.SaveChangesAsync();await tx.CommitAsync();return await GetAsync(id);}
 async Task Check(Guid id,decimal q,Guid? lot,bool own){var rows=await db.SupplyInventoryMovements.Where(x=>x.SupplyItemId==id&&(!lot.HasValue||x.SupplyInventoryLotId==lot)).Select(x=>new { MovementType = x.MovementType, Quantity = x.Quantity }).ToListAsync();if(lot.HasValue){var l=await db.SupplyInventoryLots.FirstOrDefaultAsync(x=>x.Id==lot&&x.SupplyItemId==id&&x.IsActive)??throw new ArgumentException("El lote no es válido.");if(l.InitialQuantity+rows.Sum(x=>Sign(x.MovementType)*x.Quantity)<q)throw new InvalidOperationException("La cantidad excede el saldo del lote.");}var physical=await Physical(id);if(physical<q)throw new InvalidOperationException("La operación dejaría el inventario en negativo.");var protectedUnits=own?0:await db.CremationUrnReservations.CountAsync(x=>x.SupplyItemId==id&&x.Status==UrnReservationStatus.Active);if(physical-q<protectedUnits)throw new InvalidOperationException("La operación dejaría insuficientes las unidades reservadas.");}
 async Task<decimal> Physical(Guid id)=>(await db.SupplyInventoryMovements.Where(x=>x.SupplyItemId==id).Select(x=>new { MovementType = x.MovementType, Quantity = x.Quantity }).ToListAsync()).Sum(x=>Sign(x.MovementType)*x.Quantity);
 SupplyInventoryMovement Move(Guid i,decimal q,Guid c,Guid? u,string n)=>new(){Id=Guid.NewGuid(),SupplyItemId=i,MovementType=SupplyInventoryMovementType.Consumption,Quantity=decimal.Round(q,3),UnitOfMeasure="unidad",OccurredAt=DateTime.UtcNow,Reference=$"CREMATION:{c}",Notes=n,RecordedByUserId=u,CreatedAt=DateTime.UtcNow};
 async Task<CremationInventoryDto> Map(Cremation c){var r=await db.CremationUrnReservations.AsNoTracking().Where(x=>x.CremationId==c.Id).OrderByDescending(x=>x.ReservedAt).FirstOrDefaultAsync();var f=await db.CremationInventoryFulfillments.AsNoTracking().Include(x=>x.Materials).FirstOrDefaultAsync(x=>x.CremationId==c.Id);var sid=r?.SupplyItemId??(c.UrnId.HasValue?(await db.UrnSupplyItems.AsNoTracking().FirstOrDefaultAsync(x=>x.UrnId==c.UrnId&&x.IsActive))?.SupplyItemId:null);var p=sid.HasValue?await Physical(sid.Value):0;var a=sid.HasValue?await db.CremationUrnReservations.CountAsync(x=>x.SupplyItemId==sid&&x.Status==UrnReservationStatus.Active):0;var mats=f?.Materials.Select(x=>new FulfillmentMaterialDto(x.SupplyItemId,x.SupplyItemNameSnapshot,x.Quantity,x.UnitOfMeasureSnapshot,x.LotId,x.InventoryMovementId)).ToList()??[];return new(c.Id,c.UrnId,c.Urn?.Name,p,a,p-a,r is null?null:new UrnReservationDto(r.Id,r.CremationId,r.UrnId,r.UrnNameSnapshot,r.SupplyItemId,r.SupplyItemNameSnapshot,r.Status,r.ReservedAt,r.ReservedByUserId,r.CancelledAt,r.FulfilledAt),f?.Id,f?.FulfilledAt,mats);}
 static int Sign(SupplyInventoryMovementType t)=>t is SupplyInventoryMovementType.ManualAdjustmentDecrease or SupplyInventoryMovementType.Consumption or SupplyInventoryMovementType.Waste or SupplyInventoryMovementType.PurchaseReturn or SupplyInventoryMovementType.ManufacturingConsumption?-1:1;
}
